// @generated by:gauntlet run:godseye-hermes-setup
import { execFile } from "node:child_process";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { promisify } from "node:util";
import { describe, expect, it } from "vitest";

const execute = promisify(execFile);
const script = resolve("scripts/hermes-local.mjs");
const cli = (await import(pathToFileURL(script).href)) as {
  parseArguments(args: string[]): Record<string, string>;
  hostEnvironment(environment: NodeJS.ProcessEnv): NodeJS.ProcessEnv;
};

describe("Hermes local setup CLI", () => {
  it("T-AC-708 strips inherited provider, controller and preload authority", () => {
    const actual = cli.hostEnvironment({
      PATH: "fixture-path",
      SystemRoot: "fixture-system-root",
      TEMP: "fixture-temp",
      OPENAI_API_KEY: "fixture-provider-material",
      GODSEYE_DATABASE_URL: "fixture-owner-database",
      HERMES_HOME: "fixture-global-hermes-home",
      WSLENV: "OPENAI_API_KEY:HERMES_HOME:PYTHONPATH",
      PYTHONPATH: "fixture-injected-python",
      PYTHONSTARTUP: "fixture-injected-startup",
      NODE_OPTIONS: "fixture-injected-node",
      LD_PRELOAD: "fixture-injected-library",
    });
    expect(actual).toEqual({
      PATH: "fixture-path",
      SystemRoot: "fixture-system-root",
      TEMP: "fixture-temp",
    });
  });

  it("T-AC-708 parses explicit local declarations without accepting runner commands", () => {
    expect(
      cli.parseArguments([
        "prepare",
        "--project",
        "project",
        "--environment",
        "environment",
        "--role",
        "security",
      ]),
    ).toEqual({
      action: "prepare",
      projectId: "project",
      environmentId: "environment",
      role: "security",
    });
    for (const command of ["chat", "run", "serve", "gateway", "publish", "skill-import"])
      expect(() => cli.parseArguments([command])).toThrow();
  });

  it("T-AC-708 refuses duplicate, unknown and incomplete command arguments", () => {
    for (const args of [
      ["prepare", "--role"],
      ["prepare", "--role", "security", "--role", "operations"],
      ["prepare", "--directory", "/outside"],
      ["prepare", "--role", "--model"],
      ["prepare", "--key", "fixture-private-material"],
    ])
      expect(() => cli.parseArguments(args)).toThrow();
  });

  it("T-AC-708 prints preparation help without installing or starting Hermes", async () => {
    const result = await execute(process.execPath, [script, "--help"], {
      windowsHide: true,
      timeout: 15000,
    });
    expect(result.stdout).toContain("preparation only");
    expect(result.stdout).toContain("Profiles are local declarations");
    expect(result.stderr).toBe("");
  });

  it("T-AC-708 refuses a runner request without echoing private arguments", async () => {
    const result = await execute(
      process.execPath,
      [script, "chat", "--input", "fixture-private-prompt"],
      {
        windowsHide: true,
        timeout: 15000,
      },
    ).then(
      (value) => ({ ...value, failed: false }),
      (error: unknown) => {
        if (!error || typeof error !== "object" || !("stdout" in error) || !("stderr" in error))
          throw error;
        return { stdout: String(error.stdout), stderr: String(error.stderr), failed: true };
      },
    );
    expect(result.failed).toBe(true);
    expect(result.stdout).toBe("");
    expect(result.stderr).toContain("Local Hermes setup failed");
    expect(result.stderr).not.toContain("fixture-private-prompt");
  });
});
